TLM.f("Sancti/01-08",{"officium":"Die Octava Januarii","rule":["Gloria","CredoDA","Prefatio=Epi","Suffragium=Maria2;Papa;Ecclesia;;","Infra octavam Epiphaniæ Domini"],"ruleInherited":["Gloria","Credo","Prefatio=Epi"],"fallback":"Sancti/01-06","from":{"Introitus":"Sancti/01-06","Oratio":"Sancti/01-06","Lectio":"Sancti/01-06","Graduale":"Sancti/01-06","Evangelium":"Sancti/01-06","Offertorium":"Sancti/01-06","Secreta":"Sancti/01-06","Communio":"Sancti/01-06","Postcommunio":"Sancti/01-06"},"sections":{"Introitus":[{"k":"ref","la":"Malach 3:1; 1 Par 29:12"},{"k":"text","la":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."},{"k":"ref","la":"Ps 71:1"},{"k":"text","la":"Deus, judícium tuum Regi da: et justítiam tuam Fílio Regis."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Ecce, advénit dominátor Dóminus: et regnum in manu ejus et potéstas et impérium."}],"Oratio":[{"k":"text","la":"Deus, qui hodiérna die Unigénitum tuum géntibus stella duce revelásti: concéde propítius; ut, qui jam te ex fide cognóvimus, usque ad contemplándam spéciem tuæ celsitúdinis perducámur."},{"k":"macro","name":"Per eumdem"}],"Lectio":[{"k":"text","la":"Léctio Isaíæ Prophétæ"},{"k":"ref","la":"Is 60:1-6"},{"k":"text","la":"Surge, illumináre, Jerúsalem: quia venit lumen tuum, et glória Dómini super te orta est. Quia ecce, ténebræ opérient terram et caligo pópulos: super te autem oriétur Dóminus, et glória ejus in te vidébitur. Et ambulábunt gentes in lúmine tuo, et reges in splendóre ortus tui. Leva in circúitu óculos tuos, et vide: omnes isti congregáti sunt, venérunt tibi: fílii tui de longe vénient, et fíliæ tuæ de látere surgent. Tunc vidébis et áfflues, mirábitur et dilatábitur cor tuum, quando convérsa fúerit ad te multitúdo maris, fortitúdo géntium vénerit tibi. Inundátio camelórum opériet te dromedárii Mádian et Epha: omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."}],"Graduale":[{"k":"ref","la":"Isa 60:6; 60:1"},{"k":"text","la":"Omnes de Saba vénient, aurum et thus deferéntes, et laudem Dómino annuntiántes."},{"k":"text","la":"Surge et illumináre, Jerúsalem: quia glória Dómini super te orta est. Allelúja, allelúja","mark":"V"},{"k":"ref","la":"Matt 2:2"},{"k":"text","la":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum"},{"k":"ref","la":"Matt 2:1-12"},{"k":"text","la":"Cum natus esset Jesus in Béthlehem Juda in diébus Heródis regis, ecce, Magi ab Oriénte venerunt Jerosólymam, dicéntes: Ubi est, qui natus est rex Judæórum? Vidimus enim stellam ejus in Oriénte, et vénimus adoráre eum. Audiens autem Heródes rex, turbatus est, et omnis Jerosólyma cum illo. Et cóngregans omnes principes sacerdotum et scribas pópuli, sciscitabátur ab eis, ubi Christus nasceretur. At illi dixérunt ei: In Béthlehem Judæ: sic enim scriptum est per Prophétam: Et tu, Béthlehem terra Juda, nequaquam mínima es in princípibus Juda; ex te enim éxiet dux, qui regat pópulum meum Israël. Tunc Heródes, clam vocátis Magis, diligénter dídicit ab eis tempus stellæ, quæ appáruit eis: et mittens illos in Béthlehem, dixit: Ite, et interrogáte diligénter de púero: et cum invenéritis, renuntiáte mihi, ut et ego véniens adórem eum. Qui cum audíssent regem, abiérunt. Et ecce, stella, quam víderant in Oriénte, antecedébat eos, usque dum véniens staret supra, ubi erat Puer. Vidéntes autem stellam, gavísi sunt gáudio magno valde. Et intrántes domum, invenérunt Púerum cum María Matre ejus, (hic genuflectitur) et procidéntes adoravérunt eum. Et, apértis thesáuris suis, obtulérunt ei múnera, aurum, thus et myrrham. Et respónso accépto in somnis, ne redírent ad Heródem, per aliam viam revérsi sunt in regiónem suam."}],"Offertorium":[{"k":"ref","la":"Ps 71:10-11"},{"k":"text","la":"Reges Tharsis, et ínsulæ múnera ófferent: reges Arabum et Saba dona addúcent: et adorábunt eum omnes reges terræ, omnes gentes sérvient ei."}],"Secreta":[{"k":"text","la":"Ecclésiæ tuæ, quǽsumus, Dómine, dona propítius intuere: quibus non jam aurum, thus et myrrha profertur; sed quod eisdem munéribus declarátur, immolátur et súmitur, Jesus Christus, fílius tuus, Dóminus noster:"},{"k":"macro","name":"Qui tecum"}],"Communio":[{"k":"ref","la":"Matt 2:2"},{"k":"text","la":"Vídimus stellam ejus in Oriénte, et vénimus cum munéribus adoráre Dóminum."}],"Postcommunio":[{"k":"text","la":"Præsta, quǽsumus, omnípotens Deus: ut, quæ sollémni celebrámus officio, purificátæ mentis intellegéntia consequámur."},{"k":"macro","name":"Per Dominum"}]},"hr":{"51851082a1fc32e2":{"t":"Mal 3, 1, 1 Ljet 29, 12, Ps 71, 1\n(Mal 3, 1, 1 Ljet 29, 12) Evo, došao je vladar Gospodin. U njegovoj je ruci kraljevstvo i moć i vlast. (Ps 71, 1) Bože, daj Kralju svoju sudačku vlast i svoju pravdu Kraljevu Sinu.\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Mal 3, 1, 1 Ljet 29, 12) Evo, došao je vladar Gospodin. U njegovoj je ruci kraljevstvo i moć i vlast.","kn":"(Malak. 3, 1). Eto dođe vladalac Gospodin: kraljevska je čast u ruci .njegovoj i gospo'dstvo. (P.S. 71, 1). Bože, daj kralju suđenje svoje i pravdu svoju Sinu kraljevskom! Slava Ocu . . . Eto dođe . , .","knRef":"Kniewald 1942, str. 68–69 (snimka 35) (OCR)"},"765691e1e2dea9f9":{"t":"<i>Pomolimo se</i>.\nBože, koji si na današnji dan Jedinorođenoga Sina svoga objavio narodima po zvijezdi prethodnici, podaj milostivo, da mi koji smo te već upoznali po vjeri budemo privedeni do gledanja tvoje uzvišene krasote.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Bože, koji si na današnji dan po zvijezdi, koja ih je vodila, neznabošcima otkrio Jedinorođenoga svoga, ipodaj milostivo, da m.i, koji Te već vjerom spoznas.mo, budemo privedeni do gledanja krasote visosti Tvoje, po istom G. n, I. K., Sinu Tvojem ...","knRef":"Kniewald 1942, str. 68–69 (snimka 35) (OCR)"},"23852547fbfa640a":{"t":"Iz 60, 1-6\nČitanje Izaije Proroka: Ustani, rasvijetli se, Jeruzaleme, jer je došlo tvoje svjetlo i obasjala te Gospodnja slava. Gle, zemlju će pokriti tama i narode će obaviti mrak, a nad tobom će zasjati Gospodin i na tebi će se vidjeti njegova slava. Narodi će hodati u tvojem svjetlu i kraljevi u sjaju tvoga dolaska. – Podigni svoje oči i gledaj: Svi su se ovi skupili, dolaze k tebi. Tvoji će sinovi doći izdaleka i tvoje kćeri ustat će sa svih strana. Ti ćeš to vidjeti i napunit ćeš se miline, divit će se i širiti tvoje srce, kad se mnoštvo s mora obrati prema tebi i kad silan narod dođe k tebi. Pokrit će te mnoštvo deva, dromedari iz Madijana i Efe. Svi će iz Sabe doći noseći zlato i tamjan i navješćujući Gospodnju slavu.","kn":"Čitanje proroka Izaije (80. 1-6). Ustani, zasvijetli Jeruzaleme, jer je došlo tvoje svijetlo i obasjala te Gospodnja slava. Jer evo, tama će pokriti zemlju i mrak .narode, a nad tobom će zasjati Gospodin i na tebi će se vidjeti njegova slava. 1 hodat će narodi u tvom svijetlu i kraljevi, kada sine tvoje svijetlo. Digni svoje oči 1 gledaj: Svi su se oni skupili i dolaze k tebi. Tvoji će sinovi doći izdaleka i tvoje će kćeri ustati sa strane. Tada ćeš vidjeti i sjati od dragosti, snebivat će se i širiti tvoje srce, na istoku, išla je pred njima, dok nije došla i stala kad mnoštvo s mora krene prema tebi, kada k tebi dođe ^sila naroda. Mnoštvo deva pokrit će te. dromedari iz Medijana i Efe;' svi će dolaziti iz Saibeje i donosit će zlato i tamjan i navještat će hvalu Gospodnju.","knRef":"Kniewald 1942, str. 68–69 (snimka 35) (OCR)"},"1e556b082189917a":{"t":"Iz 60, 6 i 1\nSvi će iz Sabe doći noseći zlato i tamjan i navješćujući Gospodnju slavu. Ustani, rasvijetli se, Jeruzaleme, jer te obasjala Gospodnja slava.\n\nMt 2, 2\n<i>Aleluja</i>, <i>aleluja</i>.\nVidjeli smo njegovu zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu. <i>Aleluja</i>.","kn":"(Is. 60, 6). Svi će iz Sebe doći Zlato i tamjan prinoseći i hvalu Gospodinu javljajući. Ustani, zasvijetli Jeruzaleme: jer sla\\'a te Gospodnja obasja.\n\nAleluja, aleluja. (Mat. 2, 2.) Vidjesmo zvijezdu njegovu na istoku i dodasmo s darovima da se poklonimo Gospodinu, aleluja.","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"bca9269e2481bf32":{"t":"Mt 2, 1-12\nSlijedi sveto Evanđelje po Mateju. Kad se Isus rodio u Betlehemu u Judeji za Herodova vladanja, dođu mudraci s istoka u Jeruzalem i upitaju: »Gdje je židovski kralj koji se rodio? Vidjeli smo naime njegovu zvijezdu na istoku i dođosmo da mu se poklonimo.« – Kad je kralj Herod to čuo, uznemiri se, a s njim i sav Jeruzalem. I sazove sve svećeničke poglavare i narodne pismoznance, te ih pitaše gdje Krist treba da se rodi. Oni mu odgovore: »U Betlehemu u Judeji, jer je ovako napisao prorok: I ti, Betleheme, Judina zemljo, nipošto nisi najmanji među glavnim judejskim gradovima, jer će iz tebe izići vođa koji će vladati nad mojim narodom Izraelom.« – Tada Herod potajno pozove mudrace i pomnjivo ih ispita o vremenu kada im se pojavila zvijezda. I šaljući ih u Betlehem reče im: »Pođite i raspitajte se točno za Dijete. Kad ga nađete, javite mi da i ja pođem te mu se poklonim.« – Kad su oni čuli kralja, otiđoše. I gle, zvijezda koju su vidjeli na istoku, išla je pred njima sve dok se na svom putu ne zaustavi nad mjestom gdje je bilo Dijete. I kad ugledaše zvijezdu, vrlo se obradovaše. Uđu u kuću, nađu Dijete s njegovom majkom Marijom, [OVDJE SE POKLEKNE] padnu ničice te mu se poklone. I otvore svoje blago i dadu mu darove: zlato, tamjan i miru. I opomenuti u snu da se ne vraćaju k Herodu, vrate se drugim putem u svoju zemlju.","kn":"t Slijedi sveto Etranđelje po Mateju (2, 1-12). Kad se Isus rodio u Betlehemu Judinu u vrijeme kralja Heroda, došli su s istoka mudraci u Jeruzalem i le židovski kmlj, koji se ruiio? Jer mo vidjeli na istoku njegovu zvijezdu i doSli smo mu se pokloniti. Kad je Herod to čuo, preplaši se i s njim sav Jeruzalem. I sabra sve svećLićke glavare 1 narodne književnike, te ih je ispitivao adje se rma roditi Krist. A oni mu odgZr J d ti, Betleheme. zemljo Judina, nipošto nijesi najmanji među Judinim kneževskim gradovima, jer će .z tebe izici vođa, koji će vladati nad mojim naro^ dom Izraelom. Herod tada potajno dozove mudrace-, te A točno /propita za vrijeme, kad im se pojaviLa zvijezda I posla ih u Betlehem i reče; Pođite i ispitajte točno za dijete. A kad ga nađete, javite mi da 1 ja dođem, te mu se poklonim. Kad su oni uli kralja Siđoše. I gle, zvijezda, koju su vidjeli m istoku isla je pred njima, dok nije došla i stala ed mjestom, gdje je bilo dijete. A kad ugledaše zvijezdu, vrlo se poveseliše. I ušavši u kuću, nađu duete s Manjom, njegovom majkom, i padoše nieice (ovdje se poklekne), te mu se pokloniše. I otvonse svoje blago, obdariše ga zlatom, tamjanom i dragocjenom masti. I u snu opomenuti, da se ne vra aju k Herodu, vratili su se drugim putem u SVOJU zemlju.","knRef":"Kniewald 1942, str. 62–63 (snimka 32) (OCR)"},"3fc236c7f2696475":{"t":"Ps 71, 10-11\nKraljevi Tarzisa i otoka prinijet će poklone. Kraljevi Arabije i Sabe donijet će darove. Poklonit će mu se svi zemaljski kraljevi, služit će mu svi narodi.","kn":"(Ps. 71, 10-11). Kraljevi će^Tarsa daroue prikazati, kraljevi će arapski donijeti poMone. nijemu će se pokloniti svi kraljevi zemaljski, svi ce narodi služiti njemu.","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"a1992f2804e5386e":{"t":"Milostivo pogledaj, molimo, Gospodine, darove svoje Crkve kojima ti se više ne prikazuje zlato, tamjan i mira, nego ono što se tim darovima označuje, to se žrtvuje i blaguje: Isus Krist, tvoj Sin, naš Gospodin:\n<i>koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Obazri se, molimo-, Go-s-podin-e. milostivo na darove Crkve svoje, u kojima se vise ne iznos S ta-mja-n.i smirna.. ne-go onaj, koP se tim darovima -očituje, Isus Kiris-t, Sin Tvoj, podiih naš, koji s Tobom živi i kraij-uje . . .","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"93e8203b4ea3a0a5":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi. Gospodine, sveti Oče, svemogući vječni Bože: – jer kad se tvoj Jedinorođenac pojavio u našem smrtnom tijelu, on nas je novim svjetlom svoje besmrtnosti obnovio. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","kn":"Predslovlje. Uistinu je dostojno 1 (pravedno, pravo i spasonosno, da vazda i svagdje za.hvaljujemo Tebi, Gospodine sveti. Oče svemogući, vječni Bože, jer nas je Tvoj Jedinorođeni obnovio novim svijetlom svoj® neumrlos'ti. kad se ukazao u biti naše smrtnosti. I toga redi pjevamo pjesmu slavi Tvojoj s anđelima i s arkainđelima, s prijestolima i gospodstvima, sa svom silom nebeske vojske bez prestanka govoreći:","knRef":"Kniewald 1942, str. 74–75 (snimka 38) (OCR)"},"a30154876acf1133":{"t":"Mt 2, 2\nVidjeli smo njegovu zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu.","kn":"(Mat. 2, 2). Vidjesmo zvijezdu na istoku i dođosmo s darovima da se poklonimo Gospodinu.","knRef":"Kniewald 1942, str. 70–71 (snimka 36) (OCR)"},"733012d1d7688ca9":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, svemogući Bože, da ono što svečanom službom slavimo, razumom očišćene duše i shvatimo.\n<i>Per Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus: per ómnia saecula saéculórum</i>.","kn":"Podaj, molimo, svemogući Bože, da razumijevanjem očišćene duše dostignemo presvete tajne preobraženja Sina Tvoga, što ih slavimo svečanom .službom; po istom G. n.","knRef":"Kniewald 1942, str. 670–671 (snimka 336) (OCR)"}}});
